import time
import threading

class TokenBucket:
    """Token Bucket rate limiter.

    Tokens are added at a constant rate. Each request consumes one token.
    If no tokens available, request is denied.
    """
    def __init__(self, rate: float, capacity: int):
        self.rate = rate          # Tokens per second
        self.capacity = capacity  # Max tokens
        self.tokens = capacity    # Current tokens
        self.last_refill = time.monotonic()
        self.lock = threading.Lock()

    def _refill(self):
        now = time.monotonic()
        elapsed = now - self.last_refill
        new_tokens = elapsed * self.rate
        self.tokens = min(self.capacity, self.tokens + new_tokens)
        self.last_refill = now

    def allow(self) -> bool:
        with self.lock:
            self._refill()
            if self.tokens >= 1:
                self.tokens -= 1
                return True
            return False

    def wait(self):
        """Block until a token is available."""
        while not self.allow():
            time.sleep(1 / self.rate)

# Usage
limiter = TokenBucket(rate=10, capacity=20)  # 10 req/sec, burst of 20

# Decorator
def rate_limited(limiter):
    def decorator(func):
        def wrapper(*args, **kwargs):
            if not limiter.allow():
                raise Exception("Rate limit exceeded")
            return func(*args, **kwargs)
        return wrapper
    return decorator

@rate_limited(limiter)
def api_call(data):
    return {"status": "ok", "data": data}

# Test
for i in range(25):
    try:
        result = api_call(f"request_{i}")
        print(f"✅ {i}: {result}")
    except Exception as e:
        print(f"❌ {i}: {e}")
```

**Token Bucket:** Sabit hızda token eklenir, burst traffic'e izin verir (capacity kadar). API rate limiting, network traffic shaping için idealdir.
